  const inCashPeriod=row=>periodMode||row.date.slice(0,7)===model.latestCash?.month;
  const profitBase=()=>periodMode?{revenue:model.totals.revenue,netProfit:model.totals.netProfit}:model.profit.find(row=>row.month===model.latestCash?.month);
  const forecastBase=()=>model.forecastBase||model.latestCash;
