    return {name,rows,outstanding,overdue,received,receiptTimingUnknown:rows.some(r=>r.receiptTimingUnknown),days:datedReceived?days/datedReceived:null,term:!terms.length?'—':Math.min(...terms)===Math.max(...terms)?Math.min(...terms)+'天':Math.min(...terms)+'—'+Math.max(...terms)+'天'};
