  const headers=[scenario.customerLabel||'客户',history?'已收金额':'应收余额',showReceivedShare?'已收占比':'占比','约定账期','实际平均','逾期金额','状态','建议动作'];
  const timingUnknown=customers.some(c=>c.receiptTimingUnknown),note=(history?scenario.receivableBasis.note:'实际平均按有日期的回款金额加权计算 · 点击查看原始应收记录')+(periodMode&&model.period.openingAr>0?' · 含期初待收 '+money(model.period.openingAr):'')+(timingUnknown?' · 部分已收款缺少日期，未计入本期回款图':'')+(model.ar.rows.some(r=>!r.originalInvoiceDate&&!r.invoiceDate)?' · 未提供日期的应收款单列保留':'');
